package com.securevault.service;
import com.securevault.entity.*;import com.securevault.repository.CredentialRepository;import org.springframework.stereotype.Service;import java.util.*;
@Service public class CredentialService{
 private final CredentialRepository repo;private final EncryptionService enc;public CredentialService(CredentialRepository r,EncryptionService e){repo=r;enc=e;}
 public Credential addCredential(Credential c,User u){c.setUser(u);String p=c.getPassword();c.setPassword(enc.encrypt(p));return response(repo.save(c),p);}
 public List<Credential> getUserCredentials(User u){List<Credential> out=new ArrayList<>();for(Credential c:repo.findByUser(u)){String stored=c.getPassword(),plain=stored!=null&&stored.startsWith("GCM:")?enc.decrypt(stored):stored;if(stored==null||!stored.startsWith("GCM:")){c.setPassword(enc.encrypt(plain));repo.save(c);}out.add(response(c,plain));}return out;}
 public List<Credential> search(User u,String q,String category,Boolean favorite){String x=q==null?"":q.toLowerCase();return getUserCredentials(u).stream().filter(c->(x.isBlank()||String.valueOf(c.getTitle()).toLowerCase().contains(x)||String.valueOf(c.getUsername()).toLowerCase().contains(x)||String.valueOf(c.getUrl()).toLowerCase().contains(x)||String.valueOf(c.getTags()).toLowerCase().contains(x))&&(category==null||category.isBlank()||category.equalsIgnoreCase(c.getCategory()))&&(favorite==null||favorite==c.isFavorite())).toList();}
 public Credential updateCredential(Long id,Credential u,User user){Credential c=repo.findById(id).orElseThrow(()->new RuntimeException("Credential not found"));if(!c.getUser().getId().equals(user.getId()))throw new RuntimeException("You are not allowed to modify this credential");c.setTitle(u.getTitle());c.setUsername(u.getUsername());c.setPassword(enc.encrypt(u.getPassword()));c.setUrl(u.getUrl());c.setNotes(u.getNotes());c.setCategory(u.getCategory());c.setCredentialType(u.getCredentialType());c.setFavorite(u.isFavorite());c.setTags(u.getTags());c.setPasswordExpiresAt(u.getPasswordExpiresAt());return response(repo.save(c),u.getPassword());}
 public void deleteCredential(Long id,User u){Credential c=repo.findById(id).orElseThrow(()->new RuntimeException("Credential not found"));if(!c.getUser().getId().equals(u.getId()))throw new RuntimeException("You are not allowed to delete this credential");repo.delete(c);}
 public Credential favorite(Long id,User u){Credential c=repo.findById(id).orElseThrow();if(!c.getUser().getId().equals(u.getId()))throw new RuntimeException("Forbidden");c.setFavorite(!c.isFavorite());String p=c.getPassword().startsWith("GCM:")?enc.decrypt(c.getPassword()):c.getPassword();return response(repo.save(c),p);}
 private Credential response(Credential c,String p){Credential r=new Credential();r.setId(c.getId());r.setTitle(c.getTitle());r.setUsername(c.getUsername());r.setPassword(p);r.setUrl(c.getUrl());r.setNotes(c.getNotes());r.setCategory(c.getCategory());r.setCredentialType(c.getCredentialType());r.setFavorite(c.isFavorite());r.setTags(c.getTags());r.setPasswordExpiresAt(c.getPasswordExpiresAt());r.setUser(c.getUser());return r;}
}
